mapper.select:
SELECT pn.id, pn.type, pn.title, pn.content, pn.push_time, pn.create_time, pn.expire_time
FROM public_notice pn
WHERE pn.push_time >= #{earliestTime}
  AND pn.push_time <= #{now}
  AND pn.expire_time > #{now}
  AND NOT EXISTS (
      SELECT 1
      FROM user_inbox ui
      WHERE ui.user_id = #{userId}
        AND ui.type = pn.type
        AND (ui.title = pn.title OR (ui.title IS NULL AND pn.title IS NULL))
        AND (ui.content = pn.content OR (ui.content IS NULL AND pn.content IS NULL))
        AND ui.push_time = pn.push_time
        AND ui.expire_time = pn.expire_time
  )
ORDER BY pn.push_time ASC, pn.id ASC
LIMIT #{limit}
